import React,{useRef} from 'react';
import {View,Text,ScrollView,Dimensions,Button} from 'react-native';
const {width}=Dimensions.get('window');
const pages=['{{title1}}','{{title2}}','{{title3}}'];
export default function On({onDone}:{onDone:()=>void}){
  const sv=useRef<ScrollView>(null);
  return(<View style={{flex:1}}><ScrollView ref={sv} horizontal pagingEnabled showsHorizontalScrollIndicator={false}>{pages.map((p,i)=>(<View key={i} style={{width,justifyContent:'center',alignItems:'center'}}><Text style={{fontSize:24}}>{p}</Text></View>))}</ScrollView><Button title='Done' onPress={onDone}/></View>);}
